 for(const node of [...w.scene.children])if(!counterBefore.has(node)&&node!==w.documentDisplay.mesh&&node!==w.screens.radio.mesh&&node!==w.changeToken){const p=node.position;if(p.x>=-11&&p.x<=-5&&p.z>=-3&&p.z<=0)w.counterRoot.add(node);}
 for(const node of [w.drawer,...w.counterGoods,w.storyProps[1],w.changeToken])w.counterRoot.add(node);
