export function drawBusinessScreens(w,s){
 if(!s.campaign)return;const screen=w.screens.terminal,c=screen.ctx;c.fillStyle='#0b1b13';c.fillRect(0,0,1024,768);wrap(c,'EXIT NINE / 身份登记独立终端',42,52,940,31);
 if(!s.power){wrap(c,'主电源中断 / NO SIGNAL',60,300,900,40);screen.texture.needsUpdate=true;}
 else{const p=person(s,s.idScanned);if(!p){wrap(c,'拿着顾客证件，对本电脑按 E 直接读取。',50,230,930,36);wrap(c,'头像、证件资料、登记信息、权限与工单在这里显示。',50,370,930,29);}else{drawPortrait(c,p,42,103,195,252);wrap(c,p.name+' / '+p.gender,270,135,690,34);wrap(c,p.badge+' / '+p.birth+' / '+p.height,270,205,690,25);wrap(c,'证件地址：'+p.card.address,270,265,690,28);wrap(c,'登记地址：'+p.record.address,270,320,690,28);wrap(c,'登记车辆：'+p.record.plate,42,408,940,29);wrap(c,'当班：Alex Reed 一人 / 临时调派：无',42,475,940,29);wrap(c,p.registry,42,550,940,28);const previous=previousVisit(s,p);if(previous)wrap(c,previous.trim(),42,662,940,23);wrap(c,'Q 离开电脑；面对本人 Q 还证。',42,728,940,25);}screen.texture.needsUpdate=true;}
 drawRegister(w.screens.register,s);
 const radio=w.screens.radio,rc=radio.ctx;rc.fillStyle='#13251b';rc.fillRect(0,0,1024,768);wrap(rc,'COUNTY DISPATCH / 频道 8',40,100,940,40);wrap(rc,s.storyVersion===14?'原道路频道 / 当前联系记录':'已收好 '+Object.keys(s.story).filter(k=>k.startsWith('night')).length+' 份夜班证据',40,230,940,36);const radioState=s.storyVersion===14?radioDisplay(s):null;for(const [i,label]of (radioState?radioState.rows:['上传证据并请求救援','仅发送撤离坐标']).entries()){if(i===(w.radioSelection||0)){rc.fillStyle='#9fb78d';rc.fillRect(25,330+i*130,970,105);}wrap(rc,label,50,400+i*130,930,39,i===(w.radioSelection||0)?'#122319':'#b9cfa8');}wrap(rc,radioState?radioState.footer:'W/S 选择 · E 呼叫 · Q 离开',40,705,940,30);radio.texture.needsUpdate=true;
 const pump=w.screens.pump,p=pump.ctx,pumpState=pumpDisplay(s);p.fillStyle=s.power?'#0d1d14':'#080d09';p.fillRect(0,0,1024,768);wrap(p,pumpState.header,45,100,930,42);wrap(p,pumpState.body,45,240,930,42);wrap(p,pumpState.footer,45,590,930,30);pump.texture.needsUpdate=true;
 if(!s.power){const out=w.screens.monitor;out.ctx.fillStyle='#07120c';out.ctx.fillRect(0,0,1024,768);wrap(out.ctx,'NO SIGNAL',50,360,900,40);out.texture.needsUpdate=true;}
}
export function updateBusinessWorld(w,s,dt){
 const enabled=!!s.campaign;w.idReader.visible=enabled;w.trayCard.visible=false;const handover=s.saleHandover&&s.time-s.saleHandover.time<s.saleHandover.duration?s.saleHandover:null,documentId=s.heldId||handover?.id;w.documentHand.visible=enabled&&!!documentId&&!s.carry&&!s.boardCarry&&!s.scannerActive&&!s.binocularActive&&!s.gunDrawn;
 if(!enabled){w.drawer.visible=false;w.tender.visible=false;w.receiptPaper.visible=false;w.counterGoods.forEach(g=>g.visible=false);Object.values(w.storyProps).forEach(g=>g.visible=false);return;}
 updateSafetyDrawer(w,s,dt);const t=s.transaction;const flight=s.changeFlight,elapsed=s.time-(flight?.time??-99);w.changeToken.visible=elapsed>=0&&elapsed<.45;if(w.changeToken.visible){const f=elapsed/.45;w.changeToken.position.set(-8.75+1.25*f,1.28+Math.sin(f*Math.PI)*.22,-1.18-1.6*f);}
 if(s.refusal?.refund){const u=s.refusal.time/s.refusal.duration,a=s.actors.find(a=>a.id===s.refusal.id);if(a){const destination=w.counterRoot.worldToLocal(new T.Vector3(a.x,1.18,a.z));w.changeToken.visible=true;w.changeToken.position.set(-8.75,1.22,-1.3).lerp(destination,Math.min(1,u/.85));w.changeToken.position.y+=Math.sin(u*Math.PI)*.12;}}
 w.drawer.visible=true;w.drawer.position.set(-8.75,1.11,s.drawerOpen?-1.18:-1.65);w.moneyBins.forEach((g,i)=>{g.visible=s.drawerOpen;const m=g.children[0];if(!m.userData.ownMaterial){m.material=m.material.clone();m.userData.ownMaterial=true;}const count=(s.ledger.till[DENOMINATIONS[i]]||0)-(t?.stage==='change'?(t.selected[DENOMINATIONS[i]]||0):0);m.material.emissive.setHex(i===w.cashHover?0x201a0a:0x000000);g.children.forEach(o=>{if(o.material){o.material.transparent=count<=0;o.material.opacity=count>0?1:.25;}});});w.tender.visible=t?.stage==='cash';w.receiptPaper.visible=false;w.scannerLamp.material.emissiveIntensity=s.power&&s.time-(s.scanItemTime??-99)<.4?2:.15;
 Object.entries(w.storyProps).forEach(([night,g])=>g.visible=Number(night)===s.night&&available(s,{id:'storyItem',key:Number(night)}));
 if(t&&w.tenderValue!==t.tender){w.tenderValue=t.tender;w.tenderBill.material.map=w.a.sign('US / '+money(t.tender),{bg:'#84987a',fg:'#1f3527',aspect:2.3,size:128});w.tenderBill.material.needsUpdate=true;}
 const goodsStamp=JSON.stringify([s.night,t?.id,t?.items]);if(goodsStamp!==w.goodsStamp){w.goodsStamp=goodsStamp;w.counterGoods.forEach((g,i)=>{for(const child of [...g.children])removeProduct(child);if(t?.items[i]){const mesh=createProduct(w.a,t.items[i]);mesh.castShadow=true;mesh.userData.target={id:'checkoutItem',key:i};g.add(mesh);}});}
 w.counterGoods.forEach((g,i)=>{g.visible=!!t?.items[i];if(!g.visible)return;const scanned=t.scanned.includes(i),from=new T.Vector3(-7.20+i*.31,1.105+PRODUCTS[t.items[i]].h/2,-2.28),to=new T.Vector3(-6.75+i*.31,1.105+PRODUCTS[t.items[i]].h/2,-1.45);g.position.copy(scanned?to:from);if(scanned&&s.scanItemIndex===i&&s.time-s.scanItemTime<.6){const v=(s.time-s.scanItemTime)/.6,scanner=new T.Vector3(-7.65,1.105+PRODUCTS[t.items[i]].h/2,-1.78);g.position.copy(v<.5?from.clone().lerp(scanner,v*2):scanner.lerp(to,(v-.5)*2));}});
 if(s.refusal?.returnId){const u=Math.min(1,s.refusal.time/s.refusal.duration);w.documentHand.position.z=-Math.sin(u*Math.PI)*.2;w.documentHand.visible=w.documentHand.visible&&u<.65;}else w.documentHand.position.z=handover?-Math.sin((s.time-handover.time)/handover.duration*Math.PI)*.22:0;
 if(w.documentHand.visible&&w.documentStamp!==documentId+':'+portraitReady()){w.documentStamp=documentId+':'+portraitReady();const p=person(s,documentId),out=w.documentDisplay,c=out.ctx;drawIdentity(c,p);out.texture.needsUpdate=true;}
 const stamp=JSON.stringify([s.power,s.night,s.narrative?.stage,s.narrative?.flags?.busArrived,s.narrative?.flags?.busConfirmed,s.actors?.find(a=>a.id==='leon')?.mode,s.heldId,s.trayId,t,s.drawerOpen,s.ledger.till,s.idScanRemaining>0,s.idScanned,s.idScreenMessage,s.idMarks,s.checked,s.lastSale,s.lastSale&&s.time-s.lastSale.time<8,w.documentSelection,w.documentPage,w.cashSelection,w.radioSelection,s.endingChoice,s.incidentStep,s.pumpDone,s.pumpChecked]);if(stamp!==w.businessStamp){w.businessStamp=stamp;drawBusinessScreens(w,s);}
 if(s.shadow){if(!w.shadowPerson){w.shadowPerson=makePerson(w.scene,w.a,'milo');w.shadowPerson.g.traverse(o=>{if(o.isMesh){o.material=new T.MeshBasicMaterial({color:0x111713,transparent:true,opacity:.7});o.userData={};}});}w.shadowPerson.g.visible=true;w.shadowPerson.g.position.set(s.shadow.x,0,s.shadow.z);w.shadowPerson.g.rotation.y=Math.atan2(s.player.x-s.shadow.x,s.player.z-s.shadow.z);}else if(w.shadowPerson)w.shadowPerson.g.visible=false;
}

function installSafetyDrawer(w){const a=w.a,root=w.counterRoot,wood=a.get('wood'),steel=a.plain(0x7d8676,.6,.3),dark=a.plain(0x252c25);w.safetySlide=new T.Group();root.add(w.safetySlide);w.safetySlide.position.set(-9.3,.66,-1.25);w.box(0,-.04,0,.90,.11,.42,dark,false,w.safetySlide);w.box(0,.03,.23,.94,.23,.055,wood,false,w.safetySlide,{id:'securityDrawer'});w.box(0,.04,.27,.30,.035,.055,steel,false,w.safetySlide,{id:'securityDrawer'});w.target('securityDrawer',null,-9.3,.70,-1.00,'拉开安全抽屉');
 w.gunPickup=new T.Group();w.safetySlide.add(w.gunPickup);w.gunPickup.position.set(-.19,.045,.12);w.target('gun',null,-9.49,.74,-.85,'拿起应急手枪');w.box(0,.035,0,.10,.07,.27,steel,false,w.gunPickup,{id:'gun'});const grip=w.box(0,.025,.10,.08,.06,.13,dark,false,w.gunPickup,{id:'gun'});grip.rotation.y=.35;
 w.keyPickup=new T.Group();w.safetySlide.add(w.keyPickup);w.keyPickup.position.set(.21,.06,.13);w.target('doorKey',null,-9.09,.73,-.84,'拿起门控钥匙');const ring=new T.Mesh(new T.TorusGeometry(.035,.009,6,10),steel);ring.rotation.x=Math.PI/2;ring.userData.target={id:'doorKey'};w.keyPickup.add(ring);w.box(.06,0,0,.09,.018,.025,steel,false,w.keyPickup,{id:'doorKey'});w.box(.09,-.008,.018,.02,.025,.02,steel,false,w.keyPickup,{id:'doorKey'});
 w.doorControl=w.box(-9.08,.75,-1.00,.17,.11,.07,dark,false,root,{id:'doorControl'});w.controlLamp=w.box(-9.08,.75,-.959,.045,.045,.012,a.glow(0x8e9f65,.2,false),false,root,{id:'doorControl'});w.target('doorControl',null,-9.08,.75,-.95,'使用钥匙切换前门锁');w.safetyAmount=0;
}
function updateSafetyDrawer(w,s,dt){w.safetyAmount=T.MathUtils.damp(w.safetyAmount,s.securityOpen?1:0,12,dt||.016);w.safetySlide.position.z=-1.25+w.safetyAmount*.28;w.gunPickup.visible=!s.gunOwned&&w.safetyAmount>.15;w.keyPickup.visible=!s.doorKeyOwned&&w.safetyAmount>.15;w.doorControl.visible=w.safetyAmount>.3;w.controlLamp.visible=w.safetyAmount>.3;w.controlLamp.material.emissive.setHex(s.frontLocked?0xb04a27:0x65935e);}
